// [REQ-001]
function makeId() {
  if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
}

// [REQ-003] Due dates are plain local YYYY-MM-DD strings; never parsed through UTC.
function normalizeDue(value) {
  return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
}

// [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD.
function localToday(now) {
  now = now || new Date();
  var m = String(now.getMonth() + 1).padStart(2, '0');
  var d = String(now.getDate()).padStart(2, '0');
  return now.getFullYear() + '-' + m + '-' + d;
}

// [REQ-003] Overdue = due date strictly before today's local date (date-only string compare).
function isOverdue(due, today) {
  return !!due && due < today;
}

// [REQ-004] Priority is low, med or high; anything else (including missing) is med.
function normalizePriority(value) {
  return value === 'low' || value === 'high' ? value : 'med';
}

